{
  "title": "Discussion on tax filing, domain purchase, and app profitability",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing complications",
      "claims": [
        {
          "text": "P1 paid about 1000 UAH to correctly refile taxes after an inspector approved declarations without review for 1.5 years.",
          "evidence": [1]
        },
        {
          "text": "The main difficulty is correctly matching columns and numbers in the declaration, not the tax calculation itself.",
          "evidence": [8]
        },
        {
          "text": "The whole procedure takes about one hour with Excel, once per day, and a day per month for quarterly reports.",
          "evidence": [5, 6, 7]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase discussion",
      "claims": [
        {
          "text": "P2 said they haven't bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "P4 expressed doubt that anyone would buy a domain for the project.",
          "evidence": [9, 10]
        },
        {
          "text": "P4 later described the project as a “free vibe‑code” experiment with little sense.",
          "evidence": [30]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of a web/app product",
      "claims": [
        {
          "text": "P1 researched earning on a personal project and found web platforms less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "P1 noted poor SEO, no external traffic, no ad revenue, and low user retention due to immediate paywall.",
          "evidence": [11]
        },
        {
          "text": "P1 observed a successful podcast described fast delivery (< 1 week) and a cross‑platform stack (Flutter) by copying popular apps.",
          "evidence": [12]
        },
        {
          "text": "P1 is skeptical that anyone would buy the product, betting it wouldn't sell for months.",
          "evidence": [17]
        }
      ]
    },
    {
      "id": "calculator-limitations",
      "title": "FOP calculator constraints",
      "claims": [
        {
          "text": "P1 discovered the calculator works only with Ukrainian‑currency FOPs; they had to convert all transactions using the daily exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "security-and-password",
      "title": "Password and source code concerns",
      "claims": [
        {
          "text": "P4 joked about not having paid 299 UAH for the app and hinted the password is stored in plain local storage.",
          "evidence": [22, 23]
        },
        {
          "text": "P5 called it piracy and suggested writing to the author.",
          "evidence": [24, 25]
        },
        {
          "text": "P1 believes most LinkedIn users could hack the app easily.",
          "evidence": [28]
        },
        {
          "text": "P4 described the app as a local‑first app with USD/UAH rates refreshed every 5 minutes, but the paid bundle contains hidden code.",
          "evidence": [29]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": []
}
